class MyCalendarTwo { private final List<int[]> bookings=new ArrayList<>(),overlaps=new ArrayList<>();public MyCalendarTwo(){}public boolean book(int startTime,int endTime){for(int[] overlap:overlaps)if(Math.max(startTime,overlap[0])<Math.min(endTime,overlap[1]))return false;for(int[] booking:bookings){int left=Math.max(startTime,booking[0]),right=Math.min(endTime,booking[1]);if(left<right)overlaps.add(new int[]{left,right});}bookings.add(new int[]{startTime,endTime});return true;} }
